<template>
  <q-page class="q-pa-lg">
    <!-- Header -->
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold">
          <q-icon name="notifications_active" color="amber-9" class="q-mr-sm" />
          Cấu hình Báo Động Zalo Group
        </div>
      </div>
      <div class="row q-gutter-sm">
        <q-btn outline color="primary" icon="refresh" label="Tải lại" @click="fetchConfig" />
        <q-btn
          outline
          color="amber-9"
          icon="send"
          label="Bắn Tin Test"
          @click="sendTestAlert"
          :loading="testing"
        />
        <q-btn
          unelevated
          color="primary"
          icon="save"
          label="Lưu Cấu Hình"
          @click="saveConfig"
          :loading="saving"
        />
      </div>
    </div>

    <!-- Zalo Bot Service Status Banner -->
    <q-banner
      dense
      rounded
      class="q-mb-md text-white"
      :class="bridgeStatus.zalo_connected ? (bridgeStatus.target_group_id ? 'bg-positive' : 'bg-amber-9') : (bridgeStatus.online ? 'bg-indigo-8' : 'bg-negative')"
    >
      <template #avatar>
        <q-icon
          :name="bridgeStatus.zalo_connected ? (bridgeStatus.target_group_id ? 'check_circle' : 'info') : 'qr_code_scanner'"
          color="white"
          size="28px"
        />
      </template>
      <div class="row items-center justify-between">
        <div>
          <div class="text-weight-bold" style="font-size: 15px;">
            <span v-if="bridgeStatus.zalo_connected && bridgeStatus.target_group_id">
              Zalo Bot Sẵn Sàng: Đã liên kết nhóm "{{ bridgeStatus.group_name || bridgeStatus.target_group_id }}"
            </span>
            <span v-else-if="bridgeStatus.zalo_connected">
              Zalo Bot Đã Đăng Nhập: Vui lòng vào nhóm Zalo gõ <code>/setalert</code> để nhận cảnh báo!
            </span>
            <span v-else-if="bridgeStatus.online">
              Zalo Bot Đang Chờ Đăng Nhập: Cần mở trang quét mã QR trên điện thoại để kích hoạt.
            </span>
            <span v-else>
              Dịch vụ Zalo Bridge chưa phản hồi trên cổng 5055 (đang kiểm tra).
            </span>
          </div>
          <div class="text-caption" style="opacity: 0.9;">
            Container: <b>zalo-bridge:5055</b> | Nhóm nhận tin: <b>{{ bridgeStatus.group_name || bridgeStatus.target_group_id || 'Chưa liên kết' }}</b>
          </div>
        </div>
        <div class="row q-gutter-sm items-center">
          <q-btn
            unelevated
            size="sm"
            color="white"
            text-color="dark"
            icon="open_in_new"
            label="Mở Trang Quét Mã QR"
            @click="openQrLoginPage"
          />
          <q-btn
            flat
            dense
            round
            icon="refresh"
            color="white"
            @click="fetchBridgeStatus"
          >
            <q-tooltip>Kiểm tra lại trạng thái Bot</q-tooltip>
          </q-btn>
        </div>
      </div>
    </q-banner>

    <!-- 1. Kết Nối Zalo Webhook Card -->
    <q-card class="q-mb-lg">
      <q-card-section class="row items-center justify-between bg-blue-grey-10 text-white">
        <div class="row items-center">
          <q-icon name="link" color="cyan-3" size="24px" class="q-mr-sm" />
          <div class="text-subtitle1 text-weight-bold">1. Kết Nối Zalo Webhook Bridge</div>
        </div>
        <div class="row items-center q-gutter-xs">
          <q-badge
            :color="config.is_configured ? 'positive' : 'grey-7'"
            :label="config.is_configured ? 'Webhook Đã Cấu Hình' : 'Chưa Nhập Webhook URL'"
          />
          <q-badge color="cyan-9" :label="config.alert_events.length + ' hành vi'" />
          <q-badge color="purple-9" :label="config.alert_channels.length + ' phòng'" />
        </div>
      </q-card-section>
      <q-separator />

      <q-card-section>
        <div class="row q-col-gutter-md">
          <div class="col-12 col-md-8">
            <q-input
              v-model="config.webhook_url"
              label="Zalo Webhook URL *"
              placeholder="http://zalo-bridge:5055/webhook hoặc http://127.0.0.1:5055/webhook"
              outlined
              dense
            >
              <template #prepend><q-icon name="link" color="primary" /></template>
            </q-input>
          </div>
          <div class="col-12 col-md-4">
            <q-input
              v-model="config.webhook_secret"
              label="Secret Key (Tùy chọn)"
              placeholder="Bearer Token hoặc Secret"
              outlined
              dense
              type="password"
            >
              <template #prepend><q-icon name="vpn_key" color="primary" /></template>
            </q-input>
          </div>
        </div>
      </q-card-section>
    </q-card>

    <!-- 2. Ma trận Chọn Hành Vi Báo Động Zalo -->
    <q-card class="q-mb-lg">
      <q-card-section class="row items-center justify-between bg-grey-2">
        <div class="row items-center">
          <q-icon name="checklist" color="amber-9" size="24px" class="q-mr-sm" />
          <div class="text-subtitle1 text-weight-bold text-grey-9">
            2. Chọn Loại Hành Vi Báo Động Gửi Vào Zalo
          </div>
        </div>
        <div class="row q-gutter-xs">
          <q-btn
            size="sm"
            color="negative"
            icon="shield"
            label="Chỉ Chọn Cảnh Báo Đỏ"
            @click="selectRedOnlyEvents"
          >
            <q-tooltip>Tắt hết phát hiện người vào/chuyển động, chỉ nhận ẩu đả, đột nhập, la hét</q-tooltip>
          </q-btn>
          <q-btn size="sm" outline color="primary" label="Chọn Tất Cả" @click="selectAllEvents" />
          <q-btn size="sm" outline color="grey-7" label="Bỏ Chọn Hết" @click="clearAllEvents" />
        </div>
      </q-card-section>
      <q-separator />

      <q-card-section>
        <div class="row q-col-gutter-sm">
          <div
            v-for="ev in availableEvents"
            :key="ev.code"
            class="col-12 col-sm-6 col-md-4"
          >
            <q-card
              bordered
              flat
              class="cursor-pointer q-pa-sm"
              :class="{
                'bg-red-1 text-negative': isRedEvent(ev.code) && config.alert_events.includes(ev.code),
                'bg-amber-1 text-amber-9': !isRedEvent(ev.code) && config.alert_events.includes(ev.code),
                'bg-white text-grey-7': !config.alert_events.includes(ev.code)
              }"
              @click="toggleEvent(ev.code)"
            >
              <div class="row items-center no-wrap">
                <q-checkbox
                  v-model="config.alert_events"
                  :val="ev.code"
                  dense
                  :color="isRedEvent(ev.code) ? 'negative' : 'amber-9'"
                  class="q-mr-xs"
                />
                <div class="ellipsis">
                  <div class="text-weight-bold text-caption">
                    {{ ev.label }}
                  </div>
                  <div class="text-caption text-grey-6" style="font-size: 0.72rem;">
                    Mã sự kiện: <code>{{ ev.code }}</code>
                  </div>
                </div>
              </div>
            </q-card>
          </div>
        </div>
      </q-card-section>
    </q-card>

    <!-- 3. Ma trận Chọn Camera Các Phòng Nhận Cảnh Báo -->
    <q-card class="q-mb-lg">
      <q-card-section class="row items-center justify-between bg-grey-2">
        <div class="row items-center">
          <q-icon name="videocam" color="primary" size="24px" class="q-mr-sm" />
          <div class="text-subtitle1 text-weight-bold text-grey-9">
            3. Chọn Camera Các Phòng Giám Sát ({{ config.alert_channels.length }}/{{ availableChannels.length }} phòng)
          </div>
        </div>
        <div class="row q-gutter-xs items-center">
          <q-input
            v-model="cameraSearch"
            dense
            outlined
            placeholder="Tìm phòng..."
            style="width: 180px;"
            clearable
            class="q-mr-sm"
          >
            <template #prepend><q-icon name="search" size="18px" /></template>
          </q-input>
          <q-btn size="sm" outline color="primary" label="Bật 32 Phòng" @click="selectAllChannels" />
          <q-btn size="sm" outline color="grey-7" label="Bỏ Chọn Hết" @click="clearAllChannels" />
        </div>
      </q-card-section>
      <q-separator />

      <q-card-section>
        <div class="row q-col-gutter-sm">
          <div
            v-for="cam in filteredChannels"
            :key="cam.channel"
            class="col-12 col-sm-6 col-md-4 col-lg-3"
          >
            <q-card
              bordered
              flat
              class="cursor-pointer q-pa-sm"
              :class="{
                'bg-blue-1 text-primary': config.alert_channels.includes(cam.channel),
                'bg-white text-grey-7': !config.alert_channels.includes(cam.channel)
              }"
              @click="toggleChannel(cam.channel)"
            >
              <div class="row items-center no-wrap">
                <q-checkbox
                  :model-value="config.alert_channels.includes(cam.channel)"
                  @update:model-value="toggleChannel(cam.channel)"
                  dense
                  color="primary"
                  class="q-mr-xs"
                />
                <div class="ellipsis">
                  <div class="text-weight-bold text-caption ellipsis">
                    {{ cam.name || cam.label }}
                  </div>
                  <div class="text-caption text-grey-6" style="font-size: 0.72rem;">
                    Kênh Dahua: Kênh {{ String(cam.channel).padStart(2, '0') }}
                  </div>
                </div>
              </div>
            </q-card>
          </div>
        </div>
      </q-card-section>
    </q-card>

    <!-- Bottom Action Bar -->
    <div class="row justify-between items-center q-pt-md">
      <q-btn
        outline
        color="amber-9"
        icon="send"
        label="Bắn Tin Test Thử Nghiệm"
        @click="sendTestAlert"
        :loading="testing"
        :disable="!config.webhook_url"
      />
      <q-btn
        unelevated
        color="primary"
        icon="save"
        label="Lưu Cấu Hình Nhận Thông Báo Zalo"
        @click="saveConfig"
        :loading="saving"
      />
    </div>
  </q-page>
</template>

<script>
import { defineComponent, ref, reactive, computed, onMounted, onUnmounted } from 'vue'
import { useQuasar } from 'quasar'

export default defineComponent({
  name: 'ZaloConfig',

  setup () {
    const $q = useQuasar()

    const config = reactive({
      webhook_url: '',
      webhook_secret: '',
      is_configured: false,
      alert_events: [],
      alert_channels: []
    })

    const availableEvents = ref([])
    const availableChannels = ref([])
    const cameraSearch = ref('')
    const saving = ref(false)
    const testing = ref(false)
    const bridgeStatus = ref({
      online: false,
      zalo_connected: false,
      target_group_id: '',
      group_name: '',
      invite_link: ''
    })

    const fetchBridgeStatus = async () => {
      try {
        const res = await fetch('/api/admin/zalo-status')
        if (res.ok) {
          const data = await res.json()
          bridgeStatus.value = data
        }
      } catch (e) {
        // bridgeStatus keeps default
      }
    }

    const openQrLoginPage = () => {
      const host = window.location.hostname || '127.0.0.1'
      window.open(`http://${host}:5055/login`, '_blank')
    }

    const redEventCodes = new Set([
      'Fight',
      'Intrusion',
      'CrossLine',
      'AudioMutation',
      'SoundDetection',
      'AudioAnomaly',
      'RtspSessionDisconnect'
    ])

    const isRedEvent = (code) => redEventCodes.has(code)

    const filteredChannels = computed(() => {
      if (!cameraSearch.value || !cameraSearch.value.trim()) {
        return availableChannels.value
      }
      const q = cameraSearch.value.toLowerCase().trim()
      return availableChannels.value.filter(c =>
        (c.name && c.name.toLowerCase().includes(q)) ||
        (c.label && c.label.toLowerCase().includes(q)) ||
        String(c.channel).includes(q)
      )
    })

    const fetchConfig = async () => {
      try {
        const res = await fetch('/api/admin/alert-config')
        if (res.ok) {
          const data = await res.json()
          config.webhook_url = data.zalo_webhook_url || ''
          config.webhook_secret = data.zalo_webhook_secret || ''
          config.is_configured = !!data.is_zalo_configured
          config.alert_events = Array.isArray(data.zalo_alert_events) ? data.zalo_alert_events : []
          config.alert_channels = Array.isArray(data.zalo_alert_channels) ? data.zalo_alert_channels : []
          availableEvents.value = data.available_events || []
          availableChannels.value = data.available_channels || []
        }
      } catch (e) {
        $q.notify({ type: 'negative', message: 'Lỗi tải cấu hình Zalo: ' + e.message })
      }
    }

    const saveConfig = async () => {
      saving.value = true
      try {
        const res = await fetch('/api/admin/alert-config', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            zalo_webhook_url: config.webhook_url,
            zalo_webhook_secret: config.webhook_secret,
            zalo_alert_events: config.alert_events,
            zalo_alert_channels: config.alert_channels
          })
        })
        const data = await res.json()
        if (!res.ok) throw new Error(data.detail || 'Lưu cấu hình thất bại')
        $q.notify({ type: 'positive', message: data.message || 'Đã lưu cấu hình báo động Zalo thành công!' })
        await fetchConfig()
      } catch (e) {
        $q.notify({ type: 'negative', message: e.message })
      } finally {
        saving.value = false
      }
    }

    const sendTestAlert = async () => {
      testing.value = true
      try {
        const res = await fetch('/api/admin/test-zalo', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            webhook_url: config.webhook_url,
            secret: config.webhook_secret
          })
        })
        if (!res.ok) {
          const errText = await res.text()
          throw new Error(errText || `Lỗi phản hồi HTTP ${res.status}`)
        }
        const data = await res.json()
        if (data.success) {
          $q.notify({ type: 'positive', message: data.message || 'Bắn tin test Zalo thành công!' })
        } else {
          $q.notify({ type: 'warning', message: data.message || 'Gửi test thất bại' })
        }
      } catch (e) {
        $q.notify({ type: 'negative', message: 'Lỗi kết nối Webhook Zalo: ' + e.message })
      } finally {
        testing.value = false
      }
    }

    const toggleEvent = (code) => {
      const idx = config.alert_events.indexOf(code)
      if (idx > -1) {
        config.alert_events.splice(idx, 1)
      } else {
        config.alert_events.push(code)
      }
    }

    const toggleChannel = (ch) => {
      const idx = config.alert_channels.indexOf(ch)
      if (idx > -1) {
        config.alert_channels.splice(idx, 1)
      } else {
        config.alert_channels.push(ch)
      }
    }

    const selectRedOnlyEvents = () => {
      config.alert_events = Array.from(redEventCodes)
      $q.notify({ type: 'info', message: 'Đã kích hoạt chế độ: Chỉ nhận Cảnh Báo Đỏ!' })
    }

    const selectAllEvents = () => {
      config.alert_events = availableEvents.value.map(e => e.code)
    }

    const clearAllEvents = () => {
      config.alert_events = []
    }

    const selectAllChannels = () => {
      config.alert_channels = availableChannels.value.map(c => c.channel)
    }

    const clearAllChannels = () => {
      config.alert_channels = []
    }

    let statusTimer = null
    onMounted(() => {
      fetchConfig()
      fetchBridgeStatus()
      statusTimer = setInterval(fetchBridgeStatus, 5000)
    })
    onUnmounted(() => {
      if (statusTimer) clearInterval(statusTimer)
    })

    return {
      config,
      bridgeStatus,
      availableEvents,
      availableChannels,
      cameraSearch,
      filteredChannels,
      saving,
      testing,
      isRedEvent,
      toggleEvent,
      toggleChannel,
      selectRedOnlyEvents,
      selectAllEvents,
      clearAllEvents,
      selectAllChannels,
      clearAllChannels,
      fetchConfig,
      fetchBridgeStatus,
      openQrLoginPage,
      saveConfig,
      sendTestAlert
    }
  }
})
</script>
